<template>
  <div class="row">
    <!--Navbar, selección de opciones-->

    <!--Lista de todas las tutorias, recibe todos los parámetros para el datatable-->
    <template class="col-md-12 card" v-if="actions==='LIST'">
      <div class="row" style="margin-bottom: 10px;" v-if="estado === 'VERIFICADO' && origen === 'FAC'">
        <div class="col-md-3 col-md-offset-1">
    <label>Factura</label>
    <select class="form-control" v-model="filtroFactura">
      <option value="TODOS">Todos</option>
      <option value="CON">Con Factura</option>
      <option value="SIN">Sin Factura</option>
    </select>
  </div>
</div>
      <data-tables :key="filtroFactura" v-bind="{url, propsToSearch, tableColumns, pagination, fuentePDF: 'ISAAC II'}" id="datatable">
        <template slot="buttons" slot-scope="props">
          <!--Botones para modificar o hacer otras acciones-->
          <el-tooltip class="item" effect="dark" content="Ver" placement="top">
            <a class="btn btn-simple btn-xs btn-icon btn-info" @click="Modify(props.queriedData[props.index].Id)"><i class="fa fa-edit"></i></a>
          </el-tooltip>
          <el-tooltip class="item" effect="dark" content="Eliminar" placement="top">
            <a class="btn btn-simple btn-xs btn-danger btn-icon"  @click="removeAccess(props.queriedData[props.index].Id)"><i class="fa fa-trash-alt"></i></a>
          </el-tooltip>
          <el-tooltip class="item" effect="light" content="Aprobar" placement="top">
            <input type="checkbox"
                   :value="props.queriedData[props.index].Id"
                   v-model="SelectedIds"
                   v-on:click="UpdateIds"
                   v-on:change="capturarFila(props.queriedData[props.index])"/>
          </el-tooltip>
        </template>
      </data-tables>
    </template>
    <!--Si queremos modificar-->
    <template v-if="actions==='MODIFY'">
      <div class=" col-md-12 card">
        <EditTutoria :tutoria-id="i" :action="'PUT'" :origin="origen" v-on:back="Back"></EditTutoria>
      </div>
    </template>
    <!--Enviar a aprobación-->
    <div v-if="actions==='LIST'" class="row">
      <div v-if="allIds.length>0">
        <div class="col-md-2 el-col-md-offset-2">
          <button class="btn btn-info btn-wd" @click="generatePDF">Generar PDF</button>
        </div>

        <div class="col-md-3">
          <button class="btn btn-info" @click="PDFCareer">Generar PDF por Proyecto</button>
        </div>
        <div class="col-md-2">
          <button class="btn btn-info btn-wd" @click="EraseSelected">
            <span v-if="SelectedIds.length===0">Marcar Todos</span>
            <span v-else>Desmarcar Todos</span>
          </button>
        </div>
        <div class="col-md-2" v-if="origen === 'DEPEN' || origen === 'INDEP' || origen === 'EXT' || origen === 'FAC'">
          <button class="btn btn-info btn-wd" @click="UpdateState">Enviar a Aprobacion</button>
        </div>
        <div class="col-md-3" v-if="origen === 'FAC'">
          <button class="btn btn-warning btn-wd" @click="openAsignarFactura">Asignar Datos de Factura</button>
        </div>
        <div>
          <button class="btn btn-danger btn-fill" @click="eliminarFactura">
            <i class="fa fa-trash"></i> Eliminar Datos de Factura
          </button>
        </div>
        <div class="col-md-2" v-if="origen === 'OR'">
          <button class="btn btn-info btn-wd" @click="showDateForHistoricOR">Enviar a Historico</button>
        </div>
      </div>
    </div>

    <template v-if="PDFcarrera==='SI'">
      <div class="row">
        <div class="form-group col-md-6 el-col-md-offset-5">
          <label>Proyecto</label>
          <div>
            <model-select class="select-info"
                          :options="Proyecto"
                          v-model="ProyectoModel"
                          @input="actualCarrera"
                          placeholder="Seleccione un proyecto">
            </model-select>
          </div>
        </div>
      </div>
      <div class="form-group col-md-6 el-col-md-offset-5" v-if="aparezco==='SI'">
        <reporte-proyecto :origin="origen" :state="estado" :proyecto="ProyectoModel" ></reporte-proyecto>
      </div>
    </template>
    <template v-if="actions==='TOHISTORIC'">
      <h5 class="text-center">Identificar Periodo de Proceso para enviar los registros a Historico.</h5>
      <div class="row">
        <div class="col-md-3 el-col-md-offset-3 form-group">
          <label>Segmento</label>
          <div>
            <el-select class="select-info"
                       name="segmento"
                       size="large"
                       placeholder="Segmento"
                       v-model="segmento">
              <el-option v-for="option in selectBranches"
                         class="select-danger"
                         :value="option.value"
                         :label="option.text"
                         :key="option.value">
              </el-option>
            </el-select>
            <small v-if="formError.Segmento.active" class="form-text text-muted text-danger">{{formError.Segmento.message}}</small>
          </div>
        </div>
        <div class="col-md-3">
          <label>Mes</label>
          <div>
            <el-select class="select-info"
                       name="mes"
                       size="large"
                       placeholder="Mes"
                       v-model="mes">
              <el-option v-for="option in selectMes.values"
                         class="select-danger"
                         :value="option.value"
                         :label="option.text"
                         :key="option.value">
              </el-option>
            </el-select>
            <small v-if="formError.Mes.active" class="form-text text-muted text-danger">{{formError.Mes.message}}</small>
          </div>
        </div>
        <div class="col-md-3">
          <label>Gestion</label>
          <div>
            <input class="form-control"
                   type="text"
                   name="gestion"
                   v-model="gestion"
            />
            <small v-if="isNaN(gestion)" class="form-text text-muted text-danger">El valor debe ser numérico.</small>
            <small v-if="!isNaN(gestion) && gestion!==null && gestion!=='' && ((gestion/1000)<1)" class="form-text text-muted text-danger">El valor debe tener al menos 4 dígitos.</small>
            <small v-if="formError.Gestion.active" class="form-text text-muted text-danger">{{formError.Gestion.message}}</small>
          </div>
        </div>
      </div>
      <div class="row">
        <div class="col-md-2 el-col-md-offset-9">
          <button class="btn btn-success btn-fill" @click="SendHistoric">Enviar a Historico</button>
        </div>
      </div>
    </template>


    <template v-if="actions==='ASIGNARFACTURA'">
      <div class="factura-modal-overlay">
        <div class="factura-modal-box">
      <h5 class="text-center">Asignar datos de factura a los {{ SelectedIds.length }} registro(s) seleccionado(s).</h5>
      <div class="row">
        <div class="col-md-8 el-col-md-offset-2">
          <div style="padding: 8px 12px; background: #f5f7fa; border-radius: 4px; font-size: 13px; margin-bottom: 10px;">
            <div><strong>Docente:</strong> {{ selectedRows.length ? selectedRows[0].TeacherFullName : '' }}</div>
            <div><strong>Monto total:</strong> Bs. {{ montoTotalSeleccionado }}</div>
          </div>
        </div>
      </div>
      <div class="row">
        <div class="col-md-3 el-col-md-offset-2 form-group">
          <label>NIT</label>
          <input type="text" class="form-control" v-model="factura.NIT" placeholder="NIT"/>
          <small v-if="facturaError.NIT" class="form-text text-muted text-danger">*Este valor no puede ser vacío.</small>
        </div>
        <div class="col-md-3 form-group">
          <label>N° de Factura</label>
          <input type="text" class="form-control" v-model="factura.NumeroFactura" placeholder="N° de Factura"/>
          <small v-if="facturaError.NumeroFactura" class="form-text text-muted text-danger">*Este valor no puede ser vacío.</small>
        </div>
        <div class="col-md-3 form-group" style="display: flex; align-items: flex-end;">
          <button class="btn btn-info btn-fill" @click="buscarFactura" :disabled="buscandoFactura">
            <i class="fa fa-search"></i> Buscar en SAP
          </button>
        </div>
      </div>
      <div class="row" v-if="buscandoFactura">
        <div class="col-md-12" style="text-align: center; padding: 10px;">
          <i class="fa fa-spinner fa-spin" style="font-size: 32px; color: #2196F3;"></i>
          <p style="margin-top: 8px; color: #666;">Buscando factura en SAP...</p>
        </div>
      </div>
      <div class="row">
        <div class="col-md-6 el-col-md-offset-2 form-group">
          <label>Razón Social</label>
          <input type="text" class="form-control" v-model="factura.RazonSocial" :readonly="facturaEncontradaEnSap" placeholder="Razón Social"/>
          <small v-if="facturaError.RazonSocial" class="form-text text-muted text-danger">*Este valor no puede ser vacío.</small>
        </div>
        <div class="col-md-3 form-group">
          <label>Fecha de Factura</label>
          <div>
            <date-picker v-model="factura.FechaFactura" :format="format2" :use-utc="true" :disabled="facturaEncontradaEnSap" placeholder="DD/MM/YYYY"></date-picker>
          </div>
          <small v-if="facturaError.FechaFactura" class="form-text text-muted text-danger">*Este valor no puede ser vacío.</small>
        </div>
        
      </div>
      <div class="row">
        <div class="col-md-5 el-col-md-offset-2 form-group">
          <label>Código de Autorización</label>
          <input type="text" class="form-control" v-model="factura.CodigoAutorizacion" :readonly="facturaEncontradaEnSap" placeholder="Código de Autorización"/>
          <small v-if="facturaError.CodigoAutorizacion" class="form-text text-muted text-danger">*Este valor no puede ser vacío.</small>
        </div>
        <div class="col-md-3 el-col-md-offset-2 form-group">
          <label>Monto</label>
          <input type="number" step="0.01" class="form-control" v-model.number="factura.Monto" :readonly="facturaEncontradaEnSap" placeholder="Monto"/>
          <small v-if="facturaError.Monto" class="form-text text-muted text-danger">*Debe ingresar un monto mayor a 0.</small>
        </div>
        <div class="col-md-3 form-group">
          <label>Crédito Fiscal (13%)</label>
          <input type="text" class="form-control" :value="creditoFiscalMostrar" readonly/>
        </div>
      </div>
      <div class="row">
        <div class="col-md-2 el-col-md-offset-3">
          <button class="btn btn-danger btn-fill" @click="actions='LIST'">Cancelar</button>
        </div>
        <div class="col-md-2">
          <button class="btn btn-success btn-fill" @click="saveFactura">Guardar Factura</button>
        </div>
      </div>
    </div>
      </div>
    </template>

  </div>
</template>
<script>
  import Datepicker from 'vuejs-datepicker'
  import DatePicker from 'vue2-datepicker'
  import 'vue2-datepicker/index.css'
  import 'vue2-datepicker/locale/es'
  import { ModelSelect } from 'vue-search-select'
  import EditTutoria from '../ABM/RegistroTutorias'
  import axios from 'axios'
  import swal from 'sweetalert2'
  import jsPDF from 'jspdf'
  import 'jspdf-autotable'
  import ReporteProyecto from '../ReportProjects'
  export default {
    components: {
      Datepicker,
      DatePicker,
      EditTutoria,
      ReporteProyecto,
      ModelSelect
    },
    data () {
      return {
        aparezco: 'NO',
        ProyectoModel: '',
        Proyecto: [],
        PDFcarrera: 'NO',
        mes: null,
        segmento: null,
        format2: 'DD/MM/YYYY',
        factura: {
          RazonSocial: '',
          NIT: '',
          NumeroFactura: '',
          FechaFactura: null,
          CodigoAutorizacion: '',
          Monto: null
        },
        facturaError: {
          RazonSocial: false,
          NIT: false,
          NumeroFactura: false,
          FechaFactura: false,
          CodigoAutorizacion: false,
          Monto: false
        },
        buscandoFactura: false,
        facturaEncontradaEnSap: false,
        segmentoOrigen: null,
        gestion: null,
        i: null,
        actions: 'LIST',
        SelectedIds: [],
        selectedRows: [],
        tutoriaLoaded: false,
        initialview: 'year',
        format: 'dd-MM-yyyy',
        opendate: new Date(1975, 5, 1),
        filtroFactura: 'TODOS',
        propsToSearch: ['Id', 'Proyecto', 'Modulo', 'TeacherFullName', 'TipoTarea', 'TotalNeto', 'TotalBruto'],
        tableColumns: [
          {
            prop: 'Id',
            field: 'Id',
            label: '#',
            minWidth: 15
          },
          {
            prop: 'Proyecto',
            field: 'Proyecto',
            label: 'Proyecto',
            minWidth: 20
          },
          {
            prop: 'Modulo',
            field: 'Modulo',
            label: 'Módulo',
            minWidth: 20
          },
          {
            prop: 'TeacherFullName',
            field: 'TeacherFullName',
            label: 'Profesor',
            minWidth: 60
          },
          {
            prop: 'TipoTarea',
            field: 'TipoTarea',
            label: 'Tarea',
            minWidth: 20
          },
          {
            prop: 'TotalBruto',
            field: 'TotalBruto',
            label: 'TB',
            minWidth: 25
          },
          {
            prop: 'TotalNeto',
            field: 'TotalNeto',
            label: 'TN',
            minWidth: 25
          },
          {
            prop: 'Ignored',
            field: 'Ignored',
            label: 'Dup',
            minWidth: 10
          },
          {
            prop: 'TieneFactura',
            field: 'TieneFactura',
            label: 'Factura',
            minWidth: 40
          }
        ],
        pagination: {
          perPage: 10,
          currentPage: 1,
          perPageOptions: [10, 20, 50],
          total: 0
        },
        tutoria: null,
        create: false,
        allIds: [],
        // variables para el reporte PDF
        selectBranches: [],
        // datos de la tabla
        headers: ['Docente', 'Tarea', 'Modulo', 'Horas', 'Costo Hora', 'Total Bruto', 'Deduccion', 'IUE', 'IT', 'Total Neto', 'Observaciones', 'Dup'],
        careers: [],
        teachers: [],
        records: [],
        recordsD: [],
        careerResult: [],
        teacherResult: [],
        finalResult: [],
        finalResultD: [],
        selectMes: {
          values: [{value: '01', text: 'Enero'},
            {value: '02', text: 'Febrero'},
            {value: '03', text: 'Marzo'},
            {value: '04', text: 'Abril'},
            {value: '05', text: 'Mayo'},
            {value: '06', text: 'Junio'},
            {value: '07', text: 'Julio'},
            {value: '08', text: 'Agosto'},
            {value: '09', text: 'Septiembre'},
            {value: '10', text: 'Octubre'},
            {value: '11', text: 'Noviembre'},
            {value: '12', text: 'Diciembre'},
            {value: '13', text: 'Retroactivo Enero'},
            {value: '14', text: 'Retroactivo Febrero'},
            {value: '15', text: 'Retroactivo Marzo'},
            {value: '16', text: 'Retroactivo Abril'}]
        },
        formError: {
          Mes: {
            active: false,
            message: '*Este valor no puede ser vacio.'
          },
          Gestion: {
            active: false,
            message: '*Este valor no puede ser vacio.'
          },
          Segmento: {
            active: false,
            message: '*Este valor no puede ser vacio.'
          }
        }
      }
    },
    computed: {
      montoTotalSeleccionado () {
        var total = this.selectedRows.reduce(function (s, r) {
          return s + (parseFloat(r.TotalNeto) || 0)
        }, 0)
        return total.toFixed(2)
      },
      creditoFiscalMostrar () {
      if (this.facturaEncontradaEnSap) {
        return this.factura.CreditoFiscal || 0
      }
      var m = Number(this.factura.Monto) || 0
      return Math.round(m * 0.13 * 100) / 100
    },
    url () {
      var base = '/AsesoriaPostgrado?by=' + this.estado + '-' + this.origen
      if (this.filtroFactura === 'CON') base += '&factura=CON'
      else if (this.filtroFactura === 'SIN') base += '&factura=SIN'
      return base
    }
    },
    props: {
      // INDEPENDIENTE, DEPENDIENTE, OR
      origen: {
        required: true
      },
      // REGISTRADO, PRE-APROBADO, APROBADO
      estado: {
        required: true
      },
      // Para complementar el titulo del reporte PDF
      tipo: {
        required: true
      }
    },
    methods: {
      fakeLoad () {
        this.$store.commit('crud/loadSetter', true)
        setTimeout(() => {
          this.$store.commit('crud/loadSetter', false)
        }, 2000)
      },
      actualCarrera () {
        this.fakeLoad()
        this.aparezco = 'SI'
      },
      openAsignarFactura () {
        if (this.SelectedIds.length < 1) {
          swal({
            title: 'Debe seleccionar al menos un registro.',
            text: 'Marque los registros a los que desea asignar la factura.',
            type: 'error',
            confirmButtonClass: 'btn btn-info btn-fill',
            buttonsStyling: false
          })
          return
        }

        // Validar mismo docente (chequeo suave por nombre; el backend valida por BP/CUNI)
        if (this.selectedRows.length > 0) {
          var primerDocente = this.selectedRows[0].TeacherFullName
          var todosMismo = this.selectedRows.every(function (r) { return r.TeacherFullName === primerDocente })
          if (!todosMismo) {
            swal({
              title: 'Docentes distintos',
              text: 'Solo puede asignar factura a registros del mismo docente.',
              type: 'warning',
              confirmButtonClass: 'btn btn-info btn-fill',
              buttonsStyling: false
            })
            return
          }
        }

        this.factura.RazonSocial = ''
        this.factura.NIT = ''
        this.factura.NumeroFactura = ''
        this.factura.FechaFactura = null
        this.factura.CodigoAutorizacion = ''
        this.factura.Monto = null
        this.facturaError.RazonSocial = false
        this.facturaError.NIT = false
        this.facturaError.NumeroFactura = false
        this.facturaError.FechaFactura = false
        this.facturaError.CodigoAutorizacion = false
        this.facturaError.Monto = false
        this.facturaEncontradaEnSap = false
        this.buscandoFactura = false
        this.actions = 'ASIGNARFACTURA'
      },
      saveFactura () {
        var vm = this
        var isEmpty = function (val) {
          return !val || val.toString().trim().length === 0
        }
        this.facturaError.RazonSocial = isEmpty(this.factura.RazonSocial)
        this.facturaError.NIT = isEmpty(this.factura.NIT)
        this.facturaError.NumeroFactura = isEmpty(this.factura.NumeroFactura)
        this.facturaError.FechaFactura = !this.factura.FechaFactura
        this.facturaError.CodigoAutorizacion = isEmpty(this.factura.CodigoAutorizacion)
        this.facturaError.Monto = (this.factura.Monto === null || this.factura.Monto === '' || this.factura.Monto <= 0)
        if (this.facturaError.RazonSocial || this.facturaError.NIT ||
            this.facturaError.NumeroFactura || this.facturaError.FechaFactura ||
            this.facturaError.CodigoAutorizacion || this.facturaError.Monto) {
          return
        }
        // ¿Coincide la Razón Social con el docente? (comparación por conjunto de palabras, cualquier orden)
        var hayDesajuste = false
        if (this.facturaEncontradaEnSap && this.selectedRows.length > 0) {
          var docente = (this.selectedRows[0].TeacherFullName || '').toUpperCase().split(/\s+/).filter(Boolean).sort().join(' ')
          var razon = (this.factura.RazonSocial || '').toUpperCase().split(/\s+/).filter(Boolean).sort().join(' ')
          hayDesajuste = docente !== razon
        }

        if (hayDesajuste) {
          swal({
            title: '¿Esta seguro que la razón social es correcta?',
            text: 'La Razón Social de la factura ("' + this.factura.RazonSocial + '") no coincide con el docente ("' + this.selectedRows[0].TeacherFullName + '").',
            type: 'warning',
            showCancelButton: true,
            confirmButtonText: 'Sí, continuar',
            cancelButtonText: 'Cancelar',
            confirmButtonClass: 'btn btn-success btn-fill',
            cancelButtonClass: 'btn btn-danger btn-fill',
            buttonsStyling: false
          }).then(function () {
            vm.postFactura()
          }, function (dismiss) {
            // cancelado -> no hacer nada
          })
        } else {
          this.postFactura()
        }
      },

      postFactura (confirmarDuplicado) {
        var vm = this
        var d = new Date(this.factura.FechaFactura)
        var mnth = ('0' + (d.getMonth() + 1)).slice(-2)
        var day = ('0' + d.getDate()).slice(-2)
        var isoDate = [d.getFullYear(), mnth, day].join('-')
        var payload = {
          Ids: vm.SelectedIds,
          RazonSocial: vm.factura.RazonSocial,
          NIT: vm.factura.NIT,
          NumeroFactura: vm.factura.NumeroFactura,
          FechaFactura: isoDate,
          CodigoAutorizacion: vm.factura.CodigoAutorizacion,
          Monto: vm.factura.Monto,
          CreditoFiscal: vm.factura.CreditoFiscal,
          EncontradaEnSap: vm.facturaEncontradaEnSap,
          ConfirmarDuplicado: confirmarDuplicado === true
        }
        axios.post('AsignarFacturaProyectos', payload, { headers: { token: localStorage.getItem('token') } })
          .then(function (response) {
            swal({
              title: 'Buen trabajo!!',
              text: response.data,
              type: 'success',
              confirmButtonClass: 'btn btn-success btn-fill',
              buttonsStyling: false
            }).then(function () { location.reload() })
          })
          .catch(function (error) {
            if (error.response && error.response.status === 409 && error.response.data && error.response.data.Duplicado) {
              swal({
                title: 'Factura duplicada',
                text: error.response.data.Message,
                type: 'warning',
                showCancelButton: true,
                confirmButtonText: 'Sí, continuar',
                cancelButtonText: 'Cancelar',
                confirmButtonClass: 'btn btn-success btn-fill',
                cancelButtonClass: 'btn btn-danger btn-fill',
                buttonsStyling: false
              }).then(function () {
                vm.postFactura(true)
              }, function (dismiss) {})
            } else {
              swal({
                title: 'Ups!',
                text: (error.response && error.response.data && error.response.data.Message) ? error.response.data.Message : 'No se pudieron asignar los datos de factura.',
                type: 'error',
                confirmButtonClass: 'btn btn-info btn-fill',
                buttonsStyling: false
              })
            }
          })
      },
      buscarFactura () {
        var vm = this
        var isEmpty = function (val) { return !val || val.toString().trim().length === 0 }
        if (isEmpty(this.factura.NIT) || isEmpty(this.factura.NumeroFactura) || !this.factura.FechaFactura) {
          swal({
            title: 'Datos incompletos',
            text: 'Debe ingresar NIT, N° de Factura y Fecha de Factura para buscar.',
            type: 'warning',
            confirmButtonClass: 'btn btn-info btn-fill',
            buttonsStyling: false
          })
          return
        }
        this.buscandoFactura = true
        axios.get('BuscarFacturaProyectos', { params: { nit: this.factura.NIT, numero: this.factura.NumeroFactura },
          headers: { token: localStorage.getItem('token') }
        })
        .then(function (response) {
            vm.buscandoFactura = false
            if (response.data && response.data.Found) {
              // Comparar fecha ingresada vs SAP (solo fecha, sin hora) antes de sobrescribir
              var fechaSap = response.data.FechaFactura ? new Date(response.data.FechaFactura) : null
              var fechaUsuario = vm.factura.FechaFactura ? new Date(vm.factura.FechaFactura) : null
              var mismaFecha = true
              if (fechaSap && fechaUsuario) {
                mismaFecha = fechaSap.getUTCFullYear() === fechaUsuario.getUTCFullYear() &&
                             fechaSap.getUTCMonth() === fechaUsuario.getUTCMonth() &&
                             fechaSap.getUTCDate() === fechaUsuario.getUTCDate()
              }

              var aplicarSap = function () {
                vm.factura.RazonSocial = response.data.RazonSocial || ''
                vm.factura.CodigoAutorizacion = response.data.CodigoAutorizacion || ''
                vm.factura.Monto = response.data.Monto
                if (fechaSap) vm.factura.FechaFactura = fechaSap
                vm.facturaEncontradaEnSap = true
                swal({ title: 'Factura encontrada en SAP', type: 'success', confirmButtonClass: 'btn btn-success btn-fill', buttonsStyling: false })
              }

              if (!mismaFecha) {
                var fmt = function (d) { return ('0' + d.getUTCDate()).slice(-2) + '/' + ('0' + (d.getUTCMonth() + 1)).slice(-2) + '/' + d.getUTCFullYear() }
                swal({
                  title: 'Fecha distinta',
                  text: 'La fecha que ingresó (' + fmt(fechaUsuario) + ') no coincide con la de SAP (' + fmt(fechaSap) + '). Se usará la fecha de SAP. ¿Desea continuar?',
                  type: 'warning',
                  showCancelButton: true,
                  confirmButtonText: 'Sí, usar fecha de SAP',
                  cancelButtonText: 'Cancelar',
                  confirmButtonClass: 'btn btn-success btn-fill',
                  cancelButtonClass: 'btn btn-danger btn-fill',
                  buttonsStyling: false
                }).then(function () {
                  aplicarSap()
                }, function (dismiss) {
                  // cancelado: no autollenar, el usuario puede revisar su fecha
                })
              } else {
                aplicarSap()
              }
            } else {
              // No encontrada: confirmar entrada manual
              swal({
                title: 'Factura no encontrada',
                text: 'La factura no fue encontrada, ¿desea poner los datos manualmente?',
                type: 'question',
                showCancelButton: true,
                confirmButtonText: 'Sí, ingresar manualmente',
                cancelButtonText: 'No',
                confirmButtonClass: 'btn btn-success btn-fill',
                cancelButtonClass: 'btn btn-danger btn-fill',
                buttonsStyling: false
              }).then(function () {
                // Sí: entrada manual -> campos quedan editables, facturaEncontradaEnSap ya es false
                vm.facturaEncontradaEnSap = false
              }, function (dismiss) {
                // No: no hacer nada, el usuario puede corregir NIT/Número/Fecha y volver a buscar
              })
            }
          })
          .catch(function (error) {
            vm.buscandoFactura = false
            vm.facturaEncontradaEnSap = false
            vm.factura.CreditoFiscal = response.data.CreditoFiscal
            swal({
              title: 'Ups!',
              text: (error.response && error.response.data && error.response.data.Message) ? error.response.data.Message : 'Error al buscar la factura en SAP',
              type: 'error',
              confirmButtonClass: 'btn btn-info btn-fill',
              buttonsStyling: false
            })
          })
      },
      eliminarFactura () {
        var vm = this
        if (this.SelectedIds.length < 1) {
          swal({ title: 'Debe seleccionar al menos un registro.', type: 'error', confirmButtonClass: 'btn btn-info btn-fill', buttonsStyling: false })
          return
        }
        swal({
          title: '¿Eliminar datos de factura?',
          text: 'Se eliminarán los datos de factura de ' + this.SelectedIds.length + ' registro(s). Esta acción no se puede deshacer.',
          type: 'warning',
          showCancelButton: true,
          confirmButtonText: 'Sí, eliminar',
          cancelButtonText: 'Cancelar',
          confirmButtonClass: 'btn btn-success btn-fill',
          cancelButtonClass: 'btn btn-danger btn-fill',
          buttonsStyling: false
        }).then(function () {
          axios.post('EliminarFacturaProyectos', { Ids: vm.SelectedIds }, { headers: { token: localStorage.getItem('token') } })
            .then(function (response) {
              swal({
                title: 'Listo!',
                text: response.data,
                type: 'success',
                confirmButtonClass: 'btn btn-success btn-fill',
                buttonsStyling: false
              }).then(function () { location.reload() })
            })
            .catch(function (error) {
              swal({
                title: 'Ups!',
                text: (error.response && error.response.data && error.response.data.Message) ? error.response.data.Message : 'No se pudieron eliminar los datos de factura.',
                type: 'error',
                confirmButtonClass: 'btn btn-info btn-fill',
                buttonsStyling: false
              })
            })
        }, function (dismiss) {})
      },
      capturarFila (row) {
        // Mantener selectedRows sincronizado con SelectedIds
        var idx = this.selectedRows.findIndex(function (r) { return r.Id === row.Id })
        if (this.SelectedIds.indexOf(row.Id) !== -1) {
          if (idx === -1) this.selectedRows.push(row)
        } else {
          if (idx !== -1) this.selectedRows.splice(idx, 1)
        }
      },
      showDateForHistoricOR () {
        var vm = this
        if (vm.SelectedIds.length < 1) {
          swal({
            title: 'Debe seleccionar al menos un registro antes de enviar a aprobación.',
            text: 'Intentelo nuevamente.',
            type: 'error',
            confirmButtonClass: 'btn btn-info btn-fill',
            buttonsStyling: false
          })
        } else {
          if (vm.SelectedIds.length > 200) {
            swal({
              title: 'No se puede enviar más de 200 registros a aprobación.',
              text: 'Intentelo nuevamente con menos registros.',
              type: 'error',
              confirmButtonClass: 'btn btn-info btn-fill',
              buttonsStyling: false
            })
          } else {
            this.actions = 'TOHISTORIC'
          }
        }
      },
      // Esta función loadProjects está mal, porque carga los proyectos de la base de datos que son REGISTRADOS,
      // solo deberían aparecer los proyectos que tienen registros APROBADOS, pero no hay forma de validar eso
      // debido a que el diseño en la base de datos está mal. Es por eso que se generan PDF's vacíos!.
      loadProjects () {
        let proyectos = this.Proyecto
        axios.get('/AseProyectos?by=' + this.estado + '-' + this.origen)
          .then(response => {
            response.data.forEach(function (element) {
              proyectos.push({value: element.Cod, text: element.Cod + '-' + element.Proyecto, Id: element.Cod})
            })
          })
          .catch(error => console.log(error))
        this.IsFetching = false
      },
      PDFCareer () {
        this.PDFcarrera = 'SI'
        this.loadProjects()
        if (this.origen === 'DEPEN') {
          this.origen = 'DEPEN'
        }
      },
      loadBranchData () {
        let regionals = this.selectBranches
        axios.get('branches/')
          .then(response => {
            response.data.forEach(function (element) {
              console.log('Si leo una regional')
              regionals.push({value: element.Id, text: element.Name})
            })
            this.selectBranches = regionals
          })
          .catch(error => console.log(error))
      },
      EraseSelected () {
        if (this.SelectedIds.length === 0) {
          this.SelectedIds = this.allIds
        } else {
          this.SelectedIds = []
        }
      },
      // TODO: Esta es la funcion donde envia todo a aprobacion, si es OR lo manda directo
      UpdateState () {
        var vm = this
        if (vm.SelectedIds.length < 1) {
          swal({
            title: 'Debe seleccionar al menos un registro antes de enviar a aprobación.',
            text: 'Intentelo nuevamente.',
            type: 'error',
            confirmButtonClass: 'btn btn-info btn-fill',
            buttonsStyling: false
          })
        } else {
          if (vm.SelectedIds.length > 200) {
            swal({
              title: 'No se puede enviar más de 200 registros a aprobación.',
              text: 'Intentelo nuevamente con menos registros.',
              type: 'error',
              confirmButtonClass: 'btn btn-info btn-fill',
              buttonsStyling: false
            })
          } else {
            swal({
              title: 'Se enviaran a Aprobación ' + vm.SelectedIds.length + ' registros.',
              text: '¿Esta seguro?',
              type: 'warning',
              showCancelButton: true,
              confirmButtonText: 'Si, enviar!',
              cancelButtonText: 'No, cancelar',
              confirmButtonClass: 'btn btn-success btn-fill',
              cancelButtonClass: 'btn btn-danger btn-fill',
              buttonsStyling: false
            }).then(function () {
              axios.put('ToPreAprobacionPostgrado?myArray=' + vm.SelectedIds.join())
                  .then(response => {
                    swal({
                      title: 'Buen trabajo!!',
                      text: 'Se enviaron los registros a aprobación',
                      type: 'success',
                      confirmButtonClass: 'btn btn-success btn-fill',
                      buttonsStyling: false
                    }).then(function () {
                      // la página se recarga con frescura :v
                      location.reload()
                    })
                  })
                  .catch(error => swal({
                    title: 'Hubo un problema al enviar los registros',
                    text: (error.response && error.response.data && error.response.data.Message)
                      ? error.response.data.Message
                      : 'No se pudieron enviar los registros a aprobación.',
                    type: 'error',
                    confirmButtonClass: 'btn btn-info btn-fill',
                    buttonsStyling: false
                  }))
            }, function (dismiss) {
              if (dismiss === 'cancel') {
                swal({
                  title: 'Cancelado',
                  text: 'No se envió ningún registro a aprobación',
                  type: 'error',
                  confirmButtonClass: 'btn btn-info btn-fill',
                  buttonsStyling: false
                })
              }
            })
          }
        }
      },
      SendHistoric () {
        var vm = this
        var data = this.segmento + ';' + this.mes + ';' + this.gestion
        console.log('SendHistoricPostgrado?myArray=' + vm.SelectedIds.join() + '&data=' + data)
        swal({
          title: 'Se enviaran a Historico ' + vm.SelectedIds.length + ' registros.',
          text: '¿Esta seguro?',
          type: 'warning',
          showCancelButton: true,
          confirmButtonText: 'Si, enviar!',
          cancelButtonText: 'No, cancelar',
          confirmButtonClass: 'btn btn-success btn-fill',
          cancelButtonClass: 'btn btn-danger btn-fill',
          buttonsStyling: false
        }).then(function () {
          axios.put('SendHistoricPostgrado?myArray=' + vm.SelectedIds.join() + '&data=' + data)
                .then(response => {
                  swal({
                    title: 'Buen trabajo!!',
                    text: 'Se enviaron los registros a aprobación',
                    type: 'success',
                    confirmButtonClass: 'btn btn-success btn-fill',
                    buttonsStyling: false
                  }).then(function () {
                    // la página se recarga con frescura :v
                    location.reload()
                  })
                })
                .catch(error => swal({
                  title: 'Hubo un problema al enviar los registros',
                  text: error,
                  type: 'error',
                  confirmButtonClass: 'btn btn-info btn-fill',
                  buttonsStyling: false
                }))
        }, function (dismiss) {
          if (dismiss === 'cancel') {
            swal({
              title: 'Cancelado',
              text: 'No se envió ningún registro a aprobación',
              type: 'error',
              confirmButtonClass: 'btn btn-info btn-fill',
              buttonsStyling: false
            })
          }
        })
      },
      errorMessage: function (text) {
        swal({
          title: `Ups!`,
          text: 'Ocurrio un error!\n' + text,
          buttonsStyling: false,
          confirmButtonClass: 'btn btn-success btn-fill',
          type: 'error'
        })
      },
      UpdateIds () {
        this.$emit('childinfo', this.SelectedIds)
      },
      Modify (index) {
        this.i = index
        this.actions = 'MODIFY'
      },
      Back () {
        this.actions = 'LIST'
      },
      // SON LOS IDs necesarios para marcar todo lo que esta en la tabla
      loadTutoriaIds () {
        let id = this.allIds
        axios.get('AsesoriaPostgrado?by=' + this.estado + '-' + this.origen)
          .then(response => {
            response.data.forEach(function (element) {
              // console.log(6
              id.push(element.Id)
            })
            this.allIds = id
          })
          .catch(error => console.log(error + 'Im here cause I messed up'))
      },
      removeAccess (index) {
        swal({
          title: 'Estas Seguro?',
          text: 'No será posible volver atras!',
          type: 'warning',
          showCancelButton: true,
          confirmButtonText: 'Si, borrar!',
          cancelButtonText: 'No, cancelar',
          confirmButtonClass: 'btn btn-success btn-fill',
          cancelButtonClass: 'btn btn-danger btn-fill',
          buttonsStyling: false
        }).then(function () {
          axios.delete('DeleteRecordPostgradoLote/' + index)
            .then(response => {
              swal({
                title: 'Eliminado!',
                text: 'Se elimino de forma correcta',
                type: 'success',
                confirmButtonClass: 'btn btn-success btn-fill',
                buttonsStyling: false
              }).then(function () {
                // la página se recarga con frescura :v
                location.reload()
              })
            })
            .catch(error => swal({
              title: 'No se pudo eliminar el registro',
              text: error.response.data.Message,
              type: 'error',
              confirmButtonClass: 'btn btn-info btn-fill',
              buttonsStyling: false
            }))
        }, function (dismiss) {
          if (dismiss === 'cancel') {
            swal({
              title: 'Cancelado',
              text: 'Este item está a salvo :)',
              type: 'error',
              confirmButtonClass: 'btn btn-info btn-fill',
              buttonsStyling: false
            })
          }
        })
      },
      date_function () {
        this.formattedDate = this.convert()
      },
      convert () {
        let date = new Date()
        let mnth = ('0' + (date.getMonth() + 1)).slice(-2)
        let day = ('0' + date.getDate()).slice(-2)
        return [day, mnth, date.getFullYear()].join('-')
      },
      con () {
        console.log('kheeee' + this.searchQueryProp)
      },
      // Metodo para generar el reporte
      generatePDF () {
        // Para que sea largo
        let doc = new jsPDF({ orientation: 'landscape', unit: 'mm', format: 'a3' })
        doc.setFontSize(10)
        doc.text('Fecha:' + this.formattedDate, 280, 10, null, null, 'right')
        doc.text('Fuente: ISAAC II', 280, 15, null, null, 'right')
        var img = new Image()
        img.src = './../static/img/logo_ucb3.png'
        doc.addImage(img, 'PNG', 14, 10, 20, 29)
        doc.setFontSize(22)
        doc.setFontStyle('bold')
        doc.text('Universidad Católica Boliviana "San Pablo" ', 85, 25)
        doc.setFontSize(15)
        doc.text('Actividades Académicas en Postgrado para ' + this.tipo, 85, 32)
        // Para controlar donde comienza el reporte en el eje Y
        let y = 54
        // Para no volver a pasar por un mismo índice de los registros de tutorías
        let index = 0
        // Iteración basada en el número de carreras --> número de tablas a generar
        for (let i = 0; i < this.careers.length; i++) {
          // Nombre de la carrera para filtro
          let careerName = this.careers[i]

          console.log('aqui puej:' + this.careers[i] + i)
          doc.autoTable({
            startY: y,
            head: [
              [
                {
                  content: careerName,
                  colSpan: 12,
                  styles: {halign: 'center', fillColor: [241, 196, 15]}
                }
              ]
            ],
            theme: 'grid'
          })
          // -----------------------------------Para generar la tabla con registros-------------------------------------
          // Para obtener el conteo de filas para la tabla: ocurrencias de la carrera en registros PRE-APROBADOS
          let tableLength = this.records.filter(function (tutoria) {
            console.log(tutoria.Proyecto + '=' + careerName)
            return tutoria.Proyecto === careerName
          }).length
          console.log('El número de filas para la carrera: ' + careerName + ' es:' + tableLength)
          // Cuerpo de la tabla
          let files = this.records
          let tableBody = []
          for (var tableIndex = index; tableIndex < index + tableLength; tableIndex++) {
            // Crear un array de arrays con los elementos que correspondan
            tableBody.push([files[tableIndex].TeacherFullName, files[tableIndex].Alumno, files[tableIndex].TipoTarea, files[tableIndex].Modulo, files[tableIndex].NumeroContrato, files[tableIndex].Horas, files[tableIndex].MontoHora, files[tableIndex].Total_Bruto, files[tableIndex].Deduccion, files[tableIndex].IUE, files[tableIndex].IT, files[tableIndex].IUEExt, files[tableIndex].Total_Neto, files[tableIndex].Observaciones, files[tableIndex].Dup, files[tableIndex].FacturaNIT || '', files[tableIndex].FacturaNumero || '', files[tableIndex].FacturaTipo || ''])
          }
          // console.log('this is the body with results: ')
          // console.log(tableBody)
          // Para no recorrer el array desde su primera posicion
          index = index + tableLength
          // cargamos la tabla con el cuerpo para la carrera actual
          doc.autoTable({
            startY: doc.previousAutoTable.finalY,
            head: [['Docente', 'Alumno', 'Tarea', 'Modulo', 'N° Contrato', 'Horas', 'Costo Hora', 'Total Bruto', 'Deduccion', 'RCIVA', 'IT', 'IUEExt', 'Total Neto', 'Observaciones', 'Dup', 'NIT', 'N° Fact', 'Tipo']],
            body: tableBody,
            theme: 'grid',
            styles: {cellPadding: 0.5, fontSize: 8, cellWidth: 'wrap', valign: 'middle'},
            headStyles: {
              fillColor: [4, 134, 230],
              fontSize: 8
            },
            // Las posiciones de los nombres y las observaciones se mantienen estáticas
            columnStyles: {
              text: {cellWidth: 'auto', valign: 'center'},
              0: {cellWidth: 40},
              1: {cellWidth: 40},
              2: {cellWidth: 10},
              3: {cellWidth: 40},
              4: {cellWidth: 15},
              5: {cellWidth: 7},
              6: {cellWidth: 12},
              7: {cellWidth: 12},
              8: {cellWidth: 12},
              9: {cellWidth: 12},
              10: {cellWidth: 12},
              11: {cellWidth: 12},
              12: {cellWidth: 12},
              13: {cellWidth: 23},
              14: {cellWidth: 9},
              15: {cellWidth: 18},
              16: {cellWidth: 18},
              17: {cellWidth: 8}
            }
          })
          // -------------------------------------Tabla con totales por carrera-----------------------------------------
          let careerResults = this.careerResult.filter(function (result) {
            return result.Proyecto === careerName
          })
          let resultBody = []
          resultBody.push([careerResults[0].Total_Bruto, careerResults[0].Deduccion, careerResults[0].IUE, careerResults[0].IT, careerResults[0].IUEExt, careerResults[0].Total_Neto])
          doc.autoTable({
            startY: doc.previousAutoTable.finalY,
            // para que aparezca debajo de los montos
            margin: {left: 178.2},
            theme: 'grid',
            body: resultBody,
            columnStyles: {0: {cellWidth: 12}, 1: {cellWidth: 12}, 2: {cellWidth: 12}, 3: {cellWidth: 12}, 4: {cellWidth: 12}, 5: {cellWidth: 12}},
            styles: {cellPadding: 0.5, fontSize: 8, fillColor: [222, 222, 222], fontStyle: 'bold'}
          })
          // Reset del cuerpo para otras carreras y sus resultados
          tableBody = []
          resultBody = []
          // para que el próximo título se posicione después de la tabla
          y = doc.previousAutoTable.finalY + 10
        }
        // ---------------------------------------Generar la tabla con costos finales ----------------------------------
        doc.autoTable({
          startY: y,
          theme: 'grid',
          body: this.finalResult,
          margin: {left: 178.2},
          columnStyles: {0: {cellWidth: 12}, 1: {cellWidth: 12}, 2: {cellWidth: 12}, 3: {cellWidth: 12}, 4: {cellWidth: 12}, 5: {cellWidth: 12}},
          styles: {cellPadding: 0.5, fontSize: 8, fillColor: [222, 222, 222], fontStyle: 'bold'}
        })
        doc.setFontSize(8)
        doc.setFontStyle('normal')
        doc.text('Reporte generado por: ' + this.username, 14, y + (205 - y) - 10)
        doc.save('ReporteAgrupadoPostgrado.pdf')
        return doc
      },
      // Metodos para el cuerpo del PDF
      loadCareerBody () {
        if (this.origen === 'DEPEN') {
          this.origen = 'DEPEN'
        }
        // Cargar el cuerpo, es decir datos por carrera
        let rec = this.records
        axios.get('PDFReportBodyPostgrado?part=Body;' + this.estado + ';' + this.origen)
          .then(response => {
            response.data.forEach(function (tutoria) {
              rec.push(tutoria)
            })
          })
          .catch(error => console.log(error))
        if (this.origen === 'DEPEN') {
          this.origen = 'DEPEN'
        }
      },
      loadCareerTotals () {
        // Cargar el agrupado por carrera, montos Totales
        // Cargamos los nombres de las carreras
        if (this.origen === 'DEPEN') {
          this.origen = 'DEPEN'
        }
        let uniqueCareers = this.careers
        let currentResults = this.careerResult
        axios.get('PDFReportBodyPostgrado?part=Results;' + this.estado + ';' + this.origen)
          .then(response => {
            response.data.forEach(function (element) {
              uniqueCareers.push(element.Proyecto)
              currentResults.push(element)
            })
          })
          .catch(error => console.log(error))
        if (this.origen === 'DEPEN') {
          this.origen = 'DEPEN'
        }
      },
      loadAllTotals () {
        if (this.origen === 'DEPEN') {
          this.origen = 'DEPEN'
        }
        // Cargar el total de todas las regionales que ve el usuario
        let final = this.finalResult
        axios.get('PDFReportBodyPostgrado?part=FinalResult;' + this.estado + ';' + this.origen)
          .then(response => {
            response.data.forEach(function (element) {
              final.push([element.Total_Bruto, element.Deduccion, element.IUE, element.IT, element.IUEExt, element.Total_Neto])
            })
          })
          .catch(error => console.log(error))
        if (this.origen === 'DEPEN') {
          this.origen = 'DEPEN'
        }
      },
      sayMyName () {
        axios.get('auth/UserData')
          .then(response => {
            this.username = response.data
            console.log(this.username + ' is the user who does the report')
          })
          .catch(error => console.log(error))
      }
    },
    created () {
      this.date_function()
      this.loadTutoriaIds()
      // para el reporte
      this.loadCareerBody()
      this.loadCareerTotals()
      this.loadAllTotals()
// Docente PDF
      this.loadBranchData()
      this.sayMyName()
    }
  }
</script>
<style>
  .btn-group {
    margin: 20px;
  }
  input[type=radio] {
    margin: 0 10px 0 10px;
  }
  .factura-modal-overlay {
  position: fixed;
  top: 0; left: 260px; right: 0; bottom: 0;
  background: rgba(0, 0, 0, 0.5);
  display: flex;
  align-items: center;
  justify-content: center;
  z-index: 1050;
}
.factura-modal-box {
  background: #fff;
  border-radius: 8px;
  padding: 30px;
  max-width: 900px;
  width: 90%;
  max-height: 90vh;
  overflow-y: auto;
  box-shadow: 0 10px 40px rgba(0, 0, 0, 0.3);
}
</style>



